"""Walk-forward long-only historical CVaR research backtest."""

import gzip
import hashlib
import json
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy import sparse
from scipy.optimize import linprog


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252
MIN_ORDER_FRACTION = 1e-8


def expected_sessions(start, end):
    # NYSE Group's published 2017–2024 schedules, including the 2018 mourning closure.
    if start < pd.Timestamp("2017-01-01") or end > pd.Timestamp("2024-12-31"):
        raise ValueError("This NYSE calendar covers 2017 through 2024")
    calendar = AbstractHolidayCalendar(rules=[
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ])
    closures = calendar.holidays(start, end).union(pd.DatetimeIndex(["2018-12-05"]))
    return pd.bdate_range(start, end).difference(closures)


def check_prices(prices, tickers, start, end):
    dates = prices.index
    if (
        prices.empty or not isinstance(dates, pd.DatetimeIndex) or dates.hasnans
        or dates.tz is not None or not dates.is_monotonic_increasing or dates.has_duplicates
    ):
        raise ValueError("Price history is empty or its dates are invalid")
    sessions = expected_sessions(start, end)
    missing_dates = sessions.difference(dates)
    extra_dates = dates.difference(sessions)
    if len(missing_dates) or len(extra_dates):
        raise ValueError(
            f"ETF dates differ from NYSE sessions: missing={missing_dates.strftime('%Y-%m-%d').tolist()}, "
            f"unexpected={extra_dates.strftime('%Y-%m-%d').tolist()}"
        )
    prices = prices.reindex(columns=tickers)
    valid = np.isfinite(prices) & (prices > 0)
    if not valid.to_numpy().all():
        missing = ", ".join(f"{ticker} ({count})" for ticker, count in (~valid).sum().items() if count)
        raise ValueError(f"Missing or invalid ETF close observations: {missing}")
    return prices


def load_prices(tickers, start, end, settings, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = hashlib.sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    with BytesIO(snapshot) as file:
        header = file.readline().decode("utf-8").strip()
        prefix = "# fetched_at="
        if not header.startswith(prefix):
            raise ValueError(f"Missing fetch timestamp in {Path(config_path).name}")
        fetched_at = header.removeprefix(prefix)
        if datetime.fromisoformat(fetched_at).utcoffset() is None:
            raise ValueError(f"Fetch timestamp must include a UTC offset in {Path(config_path).name}")
        prices = pd.read_csv(file, index_col="Date", parse_dates=["Date"])
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {hashlib.sha256(snapshot.partition(b'\n')[2]).hexdigest()}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return check_prices(prices, tickers, start, end), fetched_at, digest


def min_cvar(scenarios, confidence):
    observations, assets = scenarios.shape
    # Variables: ETF weights, the free VaR threshold, and one nonnegative
    # excess-loss variable per historical scenario.
    objective = np.r_[np.zeros(assets), 1.0, np.full(observations, 1 / ((1 - confidence) * observations))]
    loss_constraints = sparse.hstack(
        [sparse.csc_matrix(-scenarios), sparse.csc_matrix(-np.ones((observations, 1))),
         -sparse.eye(observations, format="csc")],
        format="csc",
    )
    budget = np.r_[np.ones(assets), np.zeros(observations + 1)].reshape(1, -1)
    result = linprog(
        objective,
        A_ub=loss_constraints,
        b_ub=np.zeros(observations),
        A_eq=budget,
        b_eq=[1.0],
        bounds=[(0.0, 1.0)] * assets + [(None, None)] + [(0.0, None)] * observations,
        method="highs",
    )
    if not result.success:
        return None
    weights = np.clip(result.x[:assets], 0.0, 1.0)
    return weights / weights.sum()


def target_schedule(returns, first_fill, config):
    lookback = config["lookback_sessions"]
    lag = config["execution_lag_sessions"]
    if first_fill - lag < lookback:
        raise ValueError("Start the price history earlier to allow a full window before the first fill")
    daily_returns = returns.to_numpy()
    sessions = returns.index
    assets = daily_returns.shape[1]
    equal_target = np.full(assets, 1.0 / assets)
    strategy_targets = {}
    benchmark_targets = {}
    cash_fallbacks = 0
    for fill in range(first_fill, len(returns), config["rebalance_every_sessions"]):
        signal = fill - lag
        scenarios = daily_returns[signal - lookback + 1 : signal + 1]
        target = min_cvar(scenarios, config["cvar_confidence"])
        if target is None:
            target = np.zeros(assets)
            cash_fallbacks += 1
        fill_date = sessions[fill]
        signal_date = sessions[signal]
        strategy_targets[fill_date] = (signal_date, target)
        benchmark_targets[fill_date] = (signal_date, equal_target)
    return strategy_targets, benchmark_targets, cash_fallbacks


def plan_fills(positions, cash, prior_close, target, target_changed, cost_rate, cash_buffer,
               min_order_fraction=MIN_ORDER_FRACTION):
    """Size signed adjusted units with only information available at the prior close."""
    invested = positions @ prior_close
    value = cash + invested
    reserve = value * cash_buffer
    minimum_amount = value * min_order_fraction
    # Only a changed target can deploy residual cash beyond the reserve.
    budget = value - reserve if target_changed else invested
    changes = target * budget / prior_close - positions
    # Close zero-target positions in full, including a fallback to cash.
    changes[(target > 0) & (np.abs(changes) * prior_close <= minimum_amount)] = 0.0
    sells = np.maximum(-changes, 0.0)
    buys = np.maximum(changes, 0.0)
    available = max(0.0, cash + (sells @ prior_close) * (1 - cost_rate) - reserve)
    estimated_debit = (buys @ prior_close) * (1 + cost_rate)
    if estimated_debit > available:
        buys *= available / estimated_debit
    buys[buys * prior_close <= minimum_amount] = 0.0
    fixed_units = buys - sells
    fixed_units.setflags(write=False)
    return fixed_units


def simulate(prices, targets, cost_rate, cash_buffer, *, min_order_fraction=MIN_ORDER_FRACTION):
    positions = np.zeros(prices.shape[1])
    cash = 1.0
    previous_target = None
    daily_results = []
    fill_details = []
    closes = prices.to_numpy()
    for day, fill_date in enumerate(prices.index[1:]):
        sizing_date = prices.index[day]
        prior_close = closes[day]
        prior_value = cash + positions @ prior_close
        planned_units = None
        scheduled = targets.get(fill_date)
        if scheduled is not None:
            signal_date, target = scheduled
            if signal_date > sizing_date:
                raise ValueError(f"Signal on {signal_date.date()} is unavailable at sizing on {sizing_date.date()}")
            target_changed = previous_target is None or not np.array_equal(target, previous_target)
            planned_units = plan_fills(
                positions, cash, prior_close, target, target_changed, cost_rate, cash_buffer,
                min_order_fraction,
            )
            previous_target = target

        # Read the next close only after the immutable quantities have been set.
        fill_close = closes[day + 1]
        turnover = 0.0
        trades = 0
        if planned_units is not None and np.any(planned_units):
            pre_fill_value = cash + positions @ fill_close
            amounts = planned_units * fill_close
            traded_value = np.abs(amounts).sum()
            cost = traded_value * cost_rate
            remaining_cash = cash - amounts.sum() - cost
            if remaining_cash < 0:
                raise RuntimeError(
                    f"Fixed quantities sized on {sizing_date.date()} would leave negative cash "
                    f"({remaining_cash:.10g}) after costs at the {fill_date.date()} close"
                )
            cash = remaining_cash
            positions += planned_units
            turnover = traded_value / pre_fill_value
            trades = np.count_nonzero(planned_units)
            units_by_ticker = dict(zip(prices.columns, planned_units.tolist()))
            fill_details.append({
                "signal_date": signal_date.date().isoformat(),
                "sizing_date": sizing_date.date().isoformat(),
                "fill_date": fill_date.date().isoformat(),
                "target_weights": dict(zip(prices.columns, target.tolist())),
                "planned_units": units_by_ticker,
                "filled_units": units_by_ticker,
                "cost": float(cost),
                "cash_after": float(cash),
            })
        value = cash + positions @ fill_close
        daily_results.append((value / prior_value - 1, turnover, trades, cash))
    columns = ["return", "turnover", "n_trades", "cash"]
    return pd.DataFrame(daily_results, index=prices.index[1:], columns=columns), fill_details


def annualized_sharpe(returns):
    vol = returns.std(ddof=1)
    if pd.isna(vol) or vol <= 0 or returns.min() == returns.max():
        return None
    return float(np.sqrt(SESSIONS_PER_YEAR) * returns.mean() / vol)


def metrics(daily, cash_proxy):
    returns = daily["return"]
    growth = np.r_[1.0, (1 + returns).cumprod().to_numpy()]
    vol = returns.std(ddof=1)
    if returns.min() == returns.max() and not pd.isna(vol):
        vol = 0.0
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(daily)) - 1),
        "ann_vol": None if pd.isna(vol) else float(vol * np.sqrt(SESSIONS_PER_YEAR)),
        "sharpe": annualized_sharpe(returns),
        "sharpe_excess": annualized_sharpe(returns - cash_proxy),
        "max_drawdown": float(np.min(growth / np.maximum.accumulate(growth) - 1)),
        "total_return": float(growth[-1] - 1),
        "turnover": float(daily["turnover"].sum()),
        "n_trades": int(daily["n_trades"].sum()),
    }


def tail_risk(returns, confidence):
    losses = -returns.to_numpy()
    threshold = np.quantile(losses, confidence, method="inverted_cdf")
    shortfall = threshold + np.maximum(losses - threshold, 0.0).mean() / (1 - confidence)
    return {"var": float(threshold), "cvar": float(shortfall)}


def print_strategy_targets(targets, universe):
    weights = [target for _, target in targets.values()]
    allocations, counts = np.unique(np.stack(weights), axis=0, return_counts=True)
    for target, count in zip(allocations, counts):
        print("STRATEGY_TARGET: " + json.dumps({
            "weights": dict(zip(universe, target.tolist())),
            "n_signals": int(count),
        }))


def print_fills(label, fill_details):
    for fill in fill_details:
        print(f"{label}_FILL: " + json.dumps(fill, allow_nan=False))


def main():
    with open(str(ROOT / "config.yaml"), "rb") as file:
        config = yaml.safe_load(file)
    universe = config["universe"]
    excess_ticker = config["excess_return_ticker"]
    tickers = [*universe, excess_ticker]
    if len(universe) < 2 or len(tickers) != len(set(tickers)) or excess_ticker != "BIL":
        raise ValueError("Use distinct ETF tickers and reserve BIL for the excess-return calculation")
    comparison_ticker = config.get("buy_and_hold_comparison")
    if comparison_ticker is not None and comparison_ticker not in universe:
        raise ValueError("The buy-and-hold comparison must be an ETF in the strategy universe")
    data_start, evaluation_start, is_end, end = (
        pd.Timestamp(config[key]) for key in ("data_start", "evaluation_start", "is_end", "evaluation_end")
    )
    if not data_start < evaluation_start <= is_end < end:
        raise ValueError("Invalid warm-up, evaluation, or split dates")
    for key in ("lookback_sessions", "execution_lag_sessions", "rebalance_every_sessions"):
        if type(config[key]) is not int or config[key] < 1:
            raise ValueError(f"{key} must be a positive integer")
    if not 0 < config["cvar_confidence"] < 1:
        raise ValueError("CVaR confidence must be between zero and one")
    commission, slippage = config["commission_bps"], config["slippage_bps"]
    if not (commission >= 0 and slippage >= 0 and commission + slippage < 10_000):
        raise ValueError("Both costs must be nonnegative and sum to less than 10,000 bps")
    cash_buffer = config["cash_buffer_bps"] / 10_000
    if not 0 < cash_buffer < 1:
        raise ValueError("Cash buffer must be positive and less than 10,000 bps")
    min_order_fraction = config.get("min_order_fraction", MIN_ORDER_FRACTION)
    if not 0 <= min_order_fraction < 1:
        raise ValueError("Minimum order fraction must be in [0, 1)")

    prices, fetched_at, snapshot_hash = load_prices(tickers, data_start, end, config, str(ROOT / "config.yaml"))
    returns = prices.pct_change(fill_method=None)
    first_fill = returns.index.searchsorted(evaluation_start)
    evaluation = returns.iloc[first_fill:]
    in_sample = evaluation.index <= is_end
    if min(in_sample.sum(), (~in_sample).sum()) < 2:
        raise ValueError("IS and OOS must each have at least two sessions")
    targets, equal_targets, cash_fallbacks = target_schedule(returns[universe], first_fill, config)
    rate = (commission + slippage) / 10_000
    trade_prices = prices[universe].iloc[first_fill - 1:]
    strategy_daily, strategy_fills = simulate(
        trade_prices, targets, rate, cash_buffer, min_order_fraction=min_order_fraction
    )
    benchmark_daily, benchmark_fills = simulate(
        trade_prices, equal_targets, rate, cash_buffer, min_order_fraction=min_order_fraction
    )
    comparison_daily = None
    if comparison_ticker is not None:
        comparison_target = np.zeros(len(universe))
        comparison_target[universe.index(comparison_ticker)] = 1.0
        initial_fill = prices.index[first_fill]
        initial_signal, _ = targets[initial_fill]
        comparison_daily, _ = simulate(
            trade_prices,
            {initial_fill: (initial_signal, comparison_target)},
            rate,
            cash_buffer,
            min_order_fraction=min_order_fraction,
        )
    masks = {"is": in_sample, "oos": ~in_sample, "full": slice(None)}
    strategy = {key: metrics(strategy_daily.loc[mask], evaluation.loc[mask, excess_ticker])
                for key, mask in masks.items()}
    benchmark = {key: metrics(benchmark_daily.loc[mask], evaluation.loc[mask, excess_ticker])
                 for key, mask in masks.items()}

    # Keep run metadata and metrics together for consumers that retain only the log tail.
    print_fills("BENCHMARK", benchmark_fills)
    print_fills("STRATEGY", strategy_fills)
    print_strategy_targets(targets, universe)
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print(f"DATA_SNAPSHOT_SHA256: {snapshot_hash}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust total-return close")
    print("PARAM_COMBOS_TRIED: 1")
    print(f"CASH_FALLBACK_REBALANCES: {cash_fallbacks}")
    print(f"CASH_BUFFER_BPS: {config['cash_buffer_bps']}")
    print("MIN_CASH_AFTER_CLOSE: " + json.dumps({
        "strategy": float(strategy_daily["cash"].min()),
        "benchmark": float(benchmark_daily["cash"].min()),
    }))
    for key in masks:
        mask = masks[key]
        dates = evaluation.loc[mask].index
        print(f"{key.upper()} {dates[0].date()} to {dates[-1].date()}")
        print(f"  Long-only CVaR: {json.dumps(strategy[key], allow_nan=False)}")
        print(f"  Equal-weight ETF benchmark: {json.dumps(benchmark[key], allow_nan=False)}")
        confidence = config["cvar_confidence"]
        net_tail_risk = {
            "confidence": confidence,
            "strategy": tail_risk(strategy_daily.loc[mask, "return"], confidence),
            "benchmark": tail_risk(benchmark_daily.loc[mask, "return"], confidence),
        }
        if comparison_daily is not None:
            comparison_period = comparison_daily.loc[mask]
            comparison = metrics(comparison_period, evaluation.loc[mask, excess_ticker])
            print(f"  {comparison_ticker} buy-and-hold: {json.dumps(comparison, allow_nan=False)}")
            net_tail_risk["buy_and_hold"] = tail_risk(comparison_period["return"], confidence)
        print("  TAIL_RISK_NET: " + json.dumps(net_tail_risk, allow_nan=False))
    results = {
        "strategy": config["strategy"],
        "data_range": f"{evaluation.index[0].date()} to {evaluation.index[-1].date()}",
        **strategy,
        "benchmark": {"name": "equal_weight_etfs", **benchmark["full"], **benchmark},
    }
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False))


if __name__ == "__main__":
    main()
